-- ROOT-ONLY reviewed operator SQL. Never called by the QA workflow.
-- Root supplies SET LOCAL zoi.qa_request / zoi.qa_issued / zoi.qa_expires
-- immediately after BEGIN. Restore additionally requires zoi.qa_sid from the
-- actual currently live dedicated QA auth.sessions row. No tokens are needed.
BEGIN;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='1s';
DO $qa$
DECLARE
 fixture constant uuid:='48c711ee-e83b-4ce2-a7cc-4126d713048a';
 workspace constant uuid:='053a5656-b19b-48a4-8721-65c4674f647c';
 profile constant uuid:='21a04e78-e3b1-448e-8517-47aad25dd5da';
 actor constant uuid:='2ba5b8e3-4fe9-4ec7-a3bf-7f616fcf07fd';
 request uuid:=nullif(current_setting('zoi.qa_request',true),'')::uuid;
 issued timestamptz:=nullif(current_setting('zoi.qa_issued',true),'')::timestamptz;
 expires timestamptz:=nullif(current_setting('zoi.qa_expires',true),'')::timestamptz;
 ids uuid[]:='{}';
 kind text; b bytea; n uuid;
 l zoi.listings; before_row jsonb; after_row jsonb;
 before_receipts text; before_owner_receipts text;

BEGIN
 IF current_user IS DISTINCT FROM 'postgres'OR current_setting('transaction_isolation')IS DISTINCT FROM 'read committed'OR request IS NULL OR issued IS NULL OR expires IS NULL OR issued>clock_timestamp()OR expires<=issued OR expires-issued>interval'30minutes'OR clock_timestamp()>=expires+interval'0seconds' THEN RAISE EXCEPTION 'private_qa_operator_scope';END IF;
 FOREACH kind IN ARRAY ARRAY['create','prepare','edit','stale']LOOP
  b:=decode(substr(encode(sha256(convert_to(request::text||':private-destination:'||kind,'UTF8')),'hex'),1,32),'hex');
  b:=set_byte(b,6,(get_byte(b,6)&15)|64);b:=set_byte(b,8,(get_byte(b,8)&63)|128);ids:=array_append(ids,encode(b,'hex')::uuid);
 END LOOP;
 PERFORM pg_advisory_xact_lock(hashtextextended('private-owner-qa:'||fixture::text,0));
 PERFORM 1 FROM zoi.workspaces WHERE id=workspace AND owner_profile_id=profile FOR SHARE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM zoi.workspace_members m JOIN zoi.user_profiles p ON p.id=m.profile_id JOIN auth.users u ON u.id=p.auth_user_id WHERE m.workspace_id=workspace AND m.profile_id=profile AND m.role='owner'AND p.auth_user_id=actor AND u.deleted_at IS NULL AND NOT coalesce(u.is_anonymous,false)AND(u.banned_until IS NULL OR u.banned_until<clock_timestamp()))THEN RAISE EXCEPTION 'private_qa_owner_changed';END IF;
